import { HttpError, requirePermission } from "@/lib/auth";
import { isValidCourseNumber, normalizeCourseNumber } from "@/lib/courseNumber";
import { errorStatus, readJson } from "@/lib/server/guard";
import { createClient } from "@/lib/supabase/server";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * POST /api/teacher/classes  { name, courseNumber }
 * Creates a class owned by the caller. The join code is generated by the database.
 */
export async function POST(req: Request) {
  try {
    const teacher = await requirePermission("class:manage");
    const body = await readJson(req);
    const name = typeof body.name === "string" ? body.name.trim() : "";
    const courseNumber = normalizeCourseNumber(typeof body.courseNumber === "string" ? body.courseNumber : "");
    if (!name || name.length > 120) throw new HttpError(400, "Give the class a name (up to 120 characters).");
    if (!isValidCourseNumber(courseNumber)) throw new HttpError(400, "Enter a course number like PHYS 1401.");

    const supabase = await createClient();
    const { data, error } = await supabase
      .from("classes")
      .insert({ teacher_id: teacher.userId, name, course_number: courseNumber, teacher_name: teacher.name.slice(0, 120) })
      .select("id, join_code")
      .single();
    if (error) {
      if (error.code === "42703" || error.code === "PGRST204") {
        throw new HttpError(503, "The database is missing the class columns. Run ducky-backend/supabase/migrations/0004_teacher_view.sql in Supabase.");
      }
      throw new Error(`create class: ${error.message}`);
    }
    return Response.json({ id: data.id, joinCode: data.join_code });
  } catch (e) {
    const { status, message } = errorStatus(e);
    return Response.json({ error: message }, { status });
  }
}
